package br.edu.ufersa.pw.todo.buggytrip.domain.service;
import br.edu.ufersa.pw.todo.buggytrip.api.dtos.Avaliacao.AvaliacaoRequest; import br.edu.ufersa.pw.todo.buggytrip.api.exceptions.*; import br.edu.ufersa.pw.todo.buggytrip.domain.entities.Usuario; import br.edu.ufersa.pw.todo.buggytrip.domain.enuns.EnumUsuario; import br.edu.ufersa.pw.todo.buggytrip.domain.repositories.AvaliacaoRepository; import org.junit.jupiter.api.*; import org.mockito.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class AvaliacaoServiceTest{@Mock AvaliacaoRepository repo;@Mock UsuarioService users;AvaliacaoService service;@BeforeEach void s(){MockitoAnnotations.openMocks(this);service=new AvaliacaoService(repo,users);}Usuario u(Long id,EnumUsuario t){var u=new Usuario();u.setId(id);u.setNome("u");u.setEmail(id+"@x");u.setSenha("x");u.setUsuarioTipo(t);return u;}AvaliacaoRequest req(){return new AvaliacaoRequest(10,9,8,9,10,8,9,"d","f",1L,2L);}@Test void cria(){when(users.get(1L)).thenReturn(u(1L,EnumUsuario.CLIENTE));when(users.get(2L)).thenReturn(u(2L,EnumUsuario.BUGUEIRO));when(repo.existsByAvaliadorIdAndBugueiroId(1L,2L)).thenReturn(false);when(repo.save(any())).thenAnswer(i->{var a=i.getArgument(0,br.edu.ufersa.pw.todo.buggytrip.domain.entities.Avaliacao.class);a.setId(1L);return a;});assertEquals(9.0,service.criar(req(),1L,false).notaMedia());}@Test void rejeitaAvaliadorInvalido(){when(users.get(1L)).thenReturn(u(1L,EnumUsuario.BUGUEIRO));when(users.get(2L)).thenReturn(u(2L,EnumUsuario.BUGUEIRO));assertThrows(BusinessRuleException.class,()->service.criar(req(),1L,false));}@Test void rejeitaDuplicidade(){when(users.get(1L)).thenReturn(u(1L,EnumUsuario.CLIENTE));when(users.get(2L)).thenReturn(u(2L,EnumUsuario.BUGUEIRO));when(repo.existsByAvaliadorIdAndBugueiroId(1L,2L)).thenReturn(true);assertThrows(ConflictException.class,()->service.criar(req(),1L,false));}}
